public static int nullSafeHashCode(long[] array) {
    if (array == null) {
        return 0;
    }
    int hashCode = 1;
    for (long element : array) {
        hashCode = 31 * hashCode + (int) (element ^ (element >>> 32));
    }
    return hashCode;
}

public class TreeNode<T> {
    T value;
    TreeNode<T> left;
    TreeNode<T> right;

    public TreeNode(T value) {
        this.value = value;
        this.left = null;
        this.right = null;
    }

    public TreeNode<T> rotateRight(TreeNode<T> node) {
        if (node == null || node.left == null) {
            return node;
        }

        TreeNode<T> newParent = node.left;
        TreeNode<T> leftRightChild = newParent.right;

        newParent.right = node;
        node.left = leftRightChild;

        return newParent;
    }
}

