public class FilePathUtils {

    /**
     * Returns the index of the last directory separator character. <p> This method will handle a file in either Unix or Windows format. The position of the last forward or backslash is returned. <p> The output will be the same irrespective of the machine that the code is running on.
     * @param filename  the filename to find the last path separator in, null returns -1
     * @return the index of the last separator character, or -1 if there is no such character
     */
    public static int indexOfLastSeparator(String filename) {
        if (filename == null) {
            return -1;
        }
        int lastUnixSeparator = filename.lastIndexOf('/');
        int lastWindowsSeparator = filename.lastIndexOf('\\');
        return Math.max(lastUnixSeparator, lastWindowsSeparator);
    }

    public static void main(String[] args) {
        System.out.println(indexOfLastSeparator("path/to/file.txt")); // Output: 10
        System.out.println(indexOfLastSeparator("C:\\path\\to\\file.txt")); // Output: 11
        System.out.println(indexOfLastSeparator("no/separator")); // Output: -1
        System.out.println(indexOfLastSeparator(null)); // Output: -1
    }
}

public class HeaderParser {

    /**
     * Skips bytes until the end of the current line.
     * @param headerPart The headers, which are being parsed.
     * @param end Index of the last byte, which has yet been processed.
     * @return Index of the \r\n sequence, which indicates end of line.
     */
    private int parseEndOfLine(String headerPart, int end) {
        int i = end;
        while (i < headerPart.length() && headerPart.charAt(i) != '\r') {
            i++;
        }
        if (i < headerPart.length() && headerPart.charAt(i) == '\r') {
            i++;
            if (i < headerPart.length() && headerPart.charAt(i) == '\n') {
                return i;
            }
        }
        return -1; // Return -1 if no \r\n sequence is found
    }

    public static void main(String[] args) {
        HeaderParser parser = new HeaderParser();
        String headers = "This is a test header\r\nwith multiple lines\r\nand a newline at the end";
        int end = headers.length() - 1;
        int result = parser.parseEndOfLine(headers, end);
        System.out.println("End of line index: " + result);
    }
}

