public class LoggingBuffer {
    private static final Logger logger = Logger.getLogger(LoggingBuffer.class);
    private final LoggingEvent[] buffer;
    private int head = 0;
    private int tail = 0;
    private int size = 0;

    public LoggingBuffer(int capacity) {
        this.buffer = new LoggingEvent[capacity];
    }

    public synchronized void put(LoggingEvent o) {
        if (size == buffer.length) {
            logger.warn("Buffer is full, silently dropping event: " + o);
            return;
        }
        buffer[tail] = o;
        tail = (tail + 1) % buffer.length;
        size++;
    }
}

