import java.util.Arrays;

public class ByteVector {
    private byte[] data;
    private int size;

    public ByteVector() {
        this.data = new byte[16];
        this.size = 0;
    }

    public ByteVector(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        this();
        if (byteArrayValue != null) {
            putByteArray(byteArrayValue, byteOffset, byteLength);
        }
    }

    public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        if (byteArrayValue == null) {
            Arrays.fill(data, size, size + byteLength, (byte) 0);
        } else {
            if (size + byteLength > data.length) {
                data = Arrays.copyOf(data, Math.max(data.length * 2, size + byteLength));
            }
            System.arraycopy(byteArrayValue, byteOffset, data, size, byteLength);
            size += byteLength;
        }
        return this;
    }

    public byte[] toByteArray() {
        return Arrays.copyOf(data, size);
    }

    public static void main(String[] args) {
        ByteVector byteVector = new ByteVector();
        byteVector.putByteArray(new byte[]{1, 2, 3}, 0, 3);
        System.out.println(Arrays.toString(byteVector.toByteArray())); // Output: [1, 2, 3]
    }
}

