}

import java.net.URI;
import java.util.ArrayList;
import java.util.List;

public class URIUtils {

    public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        List<PathSegmentImpl> pathSegments = new ArrayList<>();
        String path = u.getPath();

        if (path == null || path.isEmpty()) {
            return pathSegments;
        }

        // Remove leading '/' if it exists
        if (path.startsWith("/")) {
            path = path.substring(1);
        }

        // Split the path by '/' to get individual path segments
        String[] segments = path.split("/");

        for (String segment : segments) {
            if (decode) {
                // Decode the segment if required
                segment = java.net.URLDecoder.decode(segment, "UTF-8");
            }
            pathSegments.add(new PathSegmentImpl(segment));
        }

        return pathSegments;
    }

    // Example implementation of PathSegmentImpl
    public static class PathSegmentImpl {
        private String segment;

        public PathSegmentImpl(String segment) {
            this.segment = segment;
        }

        public String getSegment() {
            return segment;
        }
    }
}

