import java.util.Stack;

public class FrameStack {
    private Stack<Object> stack;

    public FrameStack() {
        this.stack = new Stack<>();
    }

    public void push(Object obj) {
        stack.push(obj);
    }

    public Object pop() {
        return stack.pop();
    }

    public void pop(final String descriptor) {
        int numArgs = 0;
        if (descriptor.charAt(0) == '(') {
            int balance = 0;
            for (int i = 1; i < descriptor.length(); i++) {
                if (descriptor.charAt(i) == '(') {
                    balance++;
                } else if (descriptor.charAt(i) == ')') {
                    balance--;
                }
                if (balance == 0) {
                    numArgs = i - 1;
                    break;
                }
            }
        }

        for (int i = 0; i < numArgs; i++) {
            pop();
        }
    }

    public static void main(String[] args) {
        FrameStack frameStack = new FrameStack();
        frameStack.push(1);
        frameStack.push(2);
        frameStack.push(3);
        frameStack.push(4);
        frameStack.push(5);

        frameStack.pop("()"); // Pops 2 arguments

        System.out.println(frameStack.pop()); // Should print 3
        System.out.println(frameStack.pop()); // Should print 2
        System.out.println(frameStack.pop()); // Should print 1
    }
}

import java.io.IOException;

public class ByteArrayOutputStream extends OutputStream {
    private byte[] buffer;
    private int count;

    public ByteArrayOutputStream() {
        this(1024);
    }

    public ByteArrayOutputStream(int initialSize) {
        buffer = new byte[initialSize];
        count = 0;
    }

    @Override
    public void write(final byte b[], final int off, final int len) throws IOException {
        if (b == null) {
            throw new NullPointerException("The byte array cannot be null");
        }
        if (off < 0 || len < 0 || off + len > b.length) {
            throw new IndexOutOfBoundsException("Invalid off or len values");
        }
        if (count + len > buffer.length) {
            grow(count + len);
        }
        System.arraycopy(b, off, buffer, count, len);
        count += len;
    }

    private void grow(int newCapacity) {
        int oldCapacity = buffer.length;
        int newCapacity1 = oldCapacity << 1;
        if (newCapacity1 < newCapacity) {
            newCapacity1 = newCapacity;
        }
        byte[] newBuffer = new byte[newCapacity1];
        System.arraycopy(buffer, 0, newBuffer, 0, count);
        buffer = newBuffer;
    }

    public byte[] toByteArray() {
        return Arrays.copyOf(buffer, count);
    }

    public int size() {
        return count;
    }

    public void reset() {
        count = 0;
    }
}

public static final <V> void swap(V[] arr, int i, int j) {
    if (i < 0 || i >= arr.length || j < 0 || j >= arr.length) {
        throw new IndexOutOfBoundsException("Index out of bounds");
    }
    V temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

