public class BoxSplitter {

    /** 
     * Split a box along the x axis into two equal boxes.
     * @param box the box to split
     * @return a pair with the two resulting boxes
     */
    public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
        double x = box.getX();
        double width = box.getWidth();
        double halfWidth = width / 2.0;

        Box2D box1 = new Box2D(x, 0, halfWidth, box.getHeight());
        Box2D box2 = new Box2D(x + halfWidth, 0, halfWidth, box.getHeight());

        return Pair.with(box1, box2);
    }

    public static void main(String[] args) {
        // Example usage
        Box2D box = new Box2D(0, 0, 10, 5);
        Pair<Box2D, Box2D> splitBoxes = splitAlongXAxis(box);
        System.out.println("Box 1: " + splitBoxes.getValue0());
        System.out.println("Box 2: " + splitBoxes.getValue1());
    }
}

