public class PrimeFinder {

    public static int nextPrime(int desiredCapacity) {
        if (desiredCapacity < 2) {
            return 2;
        }
        if (desiredCapacity >= 1000) {
            desiredCapacity = (int) (desiredCapacity * 1.11);
        }
        int prime = desiredCapacity;
        while (!isPrime(prime)) {
            prime++;
        }
        return prime;
    }

    private static boolean isPrime(int number) {
        if (number <= 1) {
            return false;
        }
        if (number <= 3) {
            return true;
        }
        if (number % 2 == 0 || number % 3 == 0) {
            return false;
        }
        for (int i = 5; i * i <= number; i += 6) {
            if (number % i == 0 || number % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        System.out.println(nextPrime(50)); // Output: 53
        System.out.println(nextPrime(1000)); // Output: 1111
        System.out.println(nextPrime(100)); // Output: 101
    }
}

