     * This is like {@code Character.digit()} but we don't accept non-ASCII digits.
     */
    private static int digitValue(final char c) {
        if (c >= '0' && c <= '9') {
            return c - '0';
        } else if (c >= 'a' && c <= 'z') {
            return c - 'a' + 10;
        } else if (c >= 'A' && c <= 'Z') {
            return c - 'A' + 10;
        } else {
            throw new IllegalArgumentException("Invalid digit: " + c);
        }
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(digitValue('0')); // Output: 0
        System.out.println(digitValue('9')); // Output: 9
        System.out.println(digitValue('a')); // Output: 10
        System.out.println(digitValue('f')); // Output: 15
        System.out.println(digitValue('A')); // Output: 10
        System.out.println(digitValue('F')); // Output: 15
        try {
            System.out.println(digitValue('G')); // Should throw an exception
        } catch (IllegalArgumentException e) {
            System.out.println(e.getMessage()); // Output: Invalid digit: G
        }
    }
}

