import org.apache.log4j.Appender;
import org.apache.log4j.Logger;

public class LogAppenderManager {
    private Logger logger = Logger.getLogger(LogAppenderManager.class);

    public int appendLoopOnAppenders(LoggingEvent event) {
        int count = 0;
        for (Appender appender : logger.getAllAppenders()) {
            try {
                appender.doAppend(event);
                count++;
            } catch (Exception e) {
                logger.error("Error appending event to appender: " + appender.getName(), e);
            }
        }
        return count;
    }
}

