import org.jgrapht.alg.shortestpath.DijkstraShortestPath;
import org.jgrapht.alg.shortestpath.ShortestPathAlgorithm;
import org.jgrapht.alg.shortestpath.ShortestPathResult;
import org.jgrapht.graph.GraphPath;
import org.jgrapht.graph.SimplePath;

import java.util.Set;

public class GraphTransformer {

    protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
        if (tour == null || graph == null) {
            throw new IllegalArgumentException("Tour and graph cannot be null");
        }

        // Create a simple graph to represent the path
        SimpleGraph<V, E> pathGraph = new SimpleGraph<>(graph.getEdgeFactory());

        // Add the edges from the tour to the path graph
        for (E edge : tour) {
            pathGraph.addEdge(edge.getSource(), edge.getTarget());
        }

        // Find the shortest path in the path graph
        ShortestPathAlgorithm<V, E> shortestPathAlgorithm = new DijkstraShortestPath<>(pathGraph);
        ShortestPathResult<V, E> result = shortestPathAlgorithm.getPath(pathGraph.getVertexSet().iterator().next(), pathGraph.getVertexSet().iterator().next());

        // Convert the result to a GraphPath
        return new SimplePath<>(pathGraph, result.getVertexList(), result.getEdgeList());
    }
}

