}

public class IdentifierUnescape {

    /**
     * Unescape a string DOT identifier.
     * @param input the input
     * @return the unescaped output
     */
    private String unescapeId(String input) {
        if (input == null) {
            return null;
        }
        StringBuilder result = new StringBuilder();
        boolean inEscape = false;
        for (char c : input.toCharArray()) {
            if (inEscape) {
                switch (c) {
                    case 'n':
                        result.append('\n');
                        break;
                    case 't':
                        result.append('\t');
                        break;
                    case 'r':
                        result.append('\r');
                        break;
                    case 'b':
                        result.append('\b');
                        break;
                    case 'f':
                        result.append('\f');
                        break;
                    case '\\':
                        result.append('\\');
                        break;
                    default:
                        result.append(c);
                        break;
                }
                inEscape = false;
            } else if (c == '\\') {
                inEscape = true;
            } else {
                result.append(c);
            }
        }
        return result.toString();
    }

    public static void main(String[] args) {
        IdentifierUnescape unescape = new IdentifierUnescape();
        String escaped = "a\\n\\t\\r\\b\\f\\\\";
        String unescaped = unescape.unescapeId(escaped);
        System.out.println(unescaped);  // Output: a\n\t\r\b\f\
    }
}

