import java.util.List;
import java.util.Set;

public class BucketReorganizer {

    private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
        if (bucketsByLabel == null || labels == null || minLabel < 0) {
            throw new IllegalArgumentException("Invalid input parameters");
        }

        Set<Integer> minLabelBucket = bucketsByLabel.get(minLabel);
        if (minLabelBucket == null || minLabelBucket.isEmpty()) {
            return;
        }

        for (int vertex : minLabelBucket) {
            labels.set(vertex, 0);
        }

        bucketsByLabel.set(minLabel, new HashSet<>());
    }

    public static void main(String[] args) {
        // Example usage
        List<Set<Integer>> bucketsByLabel = List.of(
            Set.of(1, 2, 3),
            Set.of(4, 5),
            Set.of(6, 7, 8, 9)
        );

        List<Integer> labels = List.of(1, 2, 3, 4, 5, 6, 7, 8, 9);

        BucketReorganizer reorganizer = new BucketReorganizer();
        reorganizer.reload(bucketsByLabel, labels, 1);

        System.out.println("Buckets by Label: " + bucketsByLabel);
        System.out.println("Labels: " + labels);
    }
}

