import java.util.Iterator;

public class Graph implements Iterator<Integer> {
    private int[] visited;
    private int currentIndex;

    public Graph(int numVertices) {
        visited = new int[numVertices];
        currentIndex = 0;
    }

    @Override
    public boolean hasNext() {
        return currentIndex < visited.length && visited[currentIndex] == 0;
    }

    @Override
    public Integer next() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }
        visited[currentIndex] = 1;
        return currentIndex++;
    }

    @Override
    public void remove() {
        if (currentIndex == 0) {
            throw new IllegalStateException();
        }
        visited[currentIndex - 1] = 0;
        currentIndex--;
    }
}

public class AbstractTypeStack {
    private Stack<AbstractType> stack;

    public AbstractTypeStack() {
        stack = new Stack<>();
    }

    public void push(AbstractType type) {
        stack.push(type);
    }

    public AbstractType pop(final int elements) {
        if (elements < 0) {
            throw new IllegalArgumentException("Number of elements to pop cannot be negative");
        }
        if (stack.size() < elements) {
            throw new IllegalStateException("Not enough elements in the stack to pop");
        }
        AbstractType[] poppedElements = new AbstractType[elements];
        for (int i = 0; i < elements; i++) {
            poppedElements[i] = stack.pop();
        }
        return poppedElements[0]; // Return the first popped element
    }

    public static void main(String[] args) {
        AbstractTypeStack stack = new AbstractTypeStack();
        stack.push(new AbstractType());
        stack.push(new AbstractType());
        stack.push(new AbstractType());

        AbstractType[] popped = stack.pop(2);
        for (AbstractType type : popped) {
            System.out.println(type);
        }
    }
}

