    /**
     * Split a String at the first occurrence of the delimiter. Does not include the delimiter in the result.
     * @param toSplit the string to split
     * @param delimiter to split the string up with
     * @return a two element array with index 0 being before the delimiter, and index 1 being after the delimiter (neither element includes the delimiter); or null if the delimiter wasn't found in the given input String
     */
    public static String[] split(String toSplit, String delimiter) {
        if (toSplit == null || delimiter == null) {
            return null;
        }
        int index = toSplit.indexOf(delimiter);
        if (index == -1) {
            return null;
        }
        return new String[]{toSplit.substring(0, index), toSplit.substring(index + delimiter.length())};
    }

    public static void main(String[] args) {
        String[] result = split("Hello, world!", ",");
        if (result != null) {
            System.out.println("Before delimiter: " + result[0]);
            System.out.println("After delimiter: " + result[1]);
        } else {
            System.out.println("Delimiter not found.");
        }
    }
}

