public class GraphProcessor {

    private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
        List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparators = new ArrayList<>();

        // Assuming graph is a predefined graph object with methods to get edges and neighbors
        for (E edge : graph.getEdges()) {
            List<Pair<Integer, Integer>> localSeparators = new ArrayList<>();
            List<Integer> neighbors = graph.getNeighbors(edge);

            for (int i = 0; i < neighbors.size(); i++) {
                for (int j = i + 1; j < neighbors.size(); j++) {
                    List<Integer> separator = new ArrayList<>();
                    separator.add(neighbors.get(i));
                    separator.add(neighbors.get(j));
                    localSeparators.add(new Pair<>(separator, edge));
