public class FileHandler {

    /**
     * Add the specified files in reverse order.
     */
    private void addReverse(final File[] files) {
        if (files == null || files.length == 0) {
            return;
        }

        // Create a copy of the files array to avoid modifying the original
        File[] reversedFiles = Arrays.copyOf(files, files.length);

        // Reverse the order of the files
        for (int i = 0; i < reversedFiles.length / 2; i++) {
            File temp = reversedFiles[i];
            reversedFiles[i] = reversedFiles[reversedFiles.length - 1 - i];
            reversedFiles[reversedFiles.length - 1 - i] = temp;
        }

        // Add the reversed files to the system or perform any other operation
        for (File file : reversedFiles) {
            System.out.println("Adding file: " + file.getAbsolutePath());
        }
    }

    public static void main(String[] args) {
        FileHandler handler = new FileHandler();
        File[] files = {new File("file1.txt"), new File("file2.txt"), new File("file3.txt")};
        handler.addReverse(files);
    }
}

