public class TableUtils {

    /**
     * Selects a specified row in the specified JTable and scrolls the specified JScrollpane to the newly selected row.
     * More importantly, the call to repaint() is delayed long enough to have the table properly paint the newly selected row which may be off-screen.
     * @param row the index of the row to select
     * @param table the JTable to select the row in
     * @param pane the JScrollpane containing the table
     */
    public static void selectRow(int row, JTable table, JScrollPane pane) {
        if (row >= 0 && row < table.getRowCount()) {
            table.setRowSelectionInterval(row, row);
            pane.getViewport().scrollRectToVisible(table.getCellRect(row, 0, true));
            try {
                Thread.sleep(100); // Delay to allow the table to repaint
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }
}

import java.util.Arrays;

public class ByteVector {
    private byte[] data;
    private int size;

    public ByteVector() {
        this.data = new byte[16];
        this.size = 0;
    }

    public ByteVector(int initialCapacity) {
        this.data = new byte[initialCapacity];
        this.size = 0;
    }

    public ByteVector putInt(final int intValue) {
        if (size + 4 > data.length) {
            data = Arrays.copyOf(data, data.length * 2);
        }
        data[size++] = (byte) (intValue >> 24);
        data[size++] = (byte) (intValue >> 16);
        data[size++] = (byte) (intValue >> 8);
        data[size++] = (byte) intValue;
        return this;
    }

    public byte[] toByteArray() {
        return Arrays.copyOf(data, size);
    }

    public static void main(String[] args) {
        ByteVector byteVector = new ByteVector();
        byteVector.putInt(123456789);
        byte[] byteArray = byteVector.toByteArray();
        System.out.println(Arrays.toString(byteArray));
    }
}

