     * @param graph the graph.
     * @param vertices the vertices to induce the subgraph from.
     * @return true if the induced subgraph is a clique.
     */
    private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
        if (vertices.size() < 2) {
            return true; // A set with 0 or 1 vertex is trivially a clique
        }

        for (V vertex : vertices) {
            for (V otherVertex : vertices) {
                if (vertex.equals(otherVertex)) {
                    continue; // Skip self-loops
                }
                if (!graph.containsEdge(vertex, otherVertex)) {
                    return false; // If there is an edge between any two vertices, it's not a clique
                }
            }
        }
        return true; // All pairs of vertices are connected, so it's a clique
    }

    public static void main(String[] args) {
        // Example usage
        Graph<String, DefaultEdge> graph = new SimpleGraph<>(DefaultEdge.class);
        graph.addVertex("A");
        graph.addVertex("B");
        graph.addVertex("C");
        graph.addEdge("A", "B");
        graph.addEdge("B", "C");
        graph.addEdge("A", "C");

        Set<String> vertices = new HashSet<>();
        vertices.add("A");
        vertices.add("B");
        vertices.add("C");

        System.out.println(isClique(graph, vertices)); // Output: true
    }
}

