public class PathUtils {

    /**
     * Apply the given relative path to the given path, assuming standard Java folder separation (i.e. "/" separators).
     * @param path the path to start from (usually a full file path)
     * @param relativePath the relative path to apply (relative to the full file path above)
     * @return the full file path that results from applying the relative path
     */
    public static String applyRelativePath(String path, String relativePath) {
        if (path == null || relativePath == null) {
            throw new IllegalArgumentException("Both path and relativePath must not be null");
        }

        // Split the path into components
        String[] pathComponents = path.split("/");
        String[] relativePathComponents = relativePath.split("/");

        // Start with the base path components
        String[] result = new String[pathComponents.length];
        System.arraycopy(pathComponents, 0, result, 0, pathComponents.length);

        // Apply the relative path components
        for (String component : relativePathComponents) {
            if (".".equals(component)) {
                // Ignore the current directory
                continue;
            } else if ("..".equals(component)) {
                // Move up one directory
                if (result.length > 0) {
                    result[result.length - 1] = null;
                }
            } else {
                // Add the new component
                result[result.length - 1] = component;
            }
        }

        // Join the result components back into a path
        StringBuilder fullPath = new StringBuilder();
        for (String component : result) {
            if (component != null) {
                if (fullPath.length() > 0) {
                    fullPath.append("/");
                }
                fullPath.append(component);
            }
        }

        return fullPath.toString();
    }

    public static void main(String[] args) {
        String path = "/home/user/documents";
        String relativePath = "folder1/subfolder2";
        System.out.println(applyRelativePath(path, relativePath)); // Output: /home/user/documents/folder1/subfolder2
    }
}

