import java.util.*;

public class Graph {
    private Map<Node, List<Edge>> adjacencyList;

    public Graph() {
        adjacencyList = new HashMap<>();
    }

    public void addNode(Node node) {
        adjacencyList.put(node, new ArrayList<>());
    }

    public void addEdge(Node from, Node to) {
        adjacencyList.get(from).add(new Edge(from, to));
    }

    public Edge edgeToNext(Node currentNode) {
        if (!adjacencyList.containsKey(currentNode)) {
            throw new IllegalArgumentException("Current node not found in the graph.");
        }

        List<Edge> edges = adjacencyList.get(currentNode);
        if (edges.isEmpty()) {
            throw new IllegalStateException("No edges connected to the current node.");
        }

        // Assuming the graph is directed and the next node is the first in the list
        return edges.get(0);
    }

    public static class Node {
        private String name;

        public Node(String name) {
            this.name = name;
        }

        @Override
        public String toString() {
            return name;
        }
    }

    public static class Edge {
        private Node from;
        private Node to;

        public Edge(Node from, Node to) {
            this.from = from;
            this.to = to;
        }

        @Override
        public String toString() {
            return from + " -> " + to;
        }
    }

    public static void main(String[] args) {
        Graph graph = new Graph();
        graph.addNode(new Node("A"));
        graph.addNode(new Node("B"));
        graph.addNode(new Node("C"));
        graph.addEdge(new Node("A"), new Node("B"));
        graph.addEdge(new Node("B"), new Node("C"));

        Edge edge = graph.edgeToNext(new Node("A"));
        System.out.println(edge); // Output: A -> B
    }
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (index < 0 || index + substring.length() > str.length()) {
        return false;
    }
    for (int i = 0; i < substring.length(); i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

import java.io.IOException;
import java.net.Socket;
import java.util.List;

public class LogAppender {
    private List<Socket> connectedClients;

    public LogAppender(List<Socket> connectedClients) {
        this.connectedClients = connectedClients;
    }

    protected void append(LoggingEvent event) {
        for (Socket client : connectedClients) {
            try {
                client.getOutputStream().write(event.getMessage().getBytes());
                client.getOutputStream().flush();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }
}

